mapper.select:
SELECT
	account_no AS accountNo,
	created_by AS createdBy,
	created_at AS createdAt,
	updated_by AS updatedBy,
	updated_at AS updatedAt,
	is_deleted AS isDeleted,
	account_id AS accountId,
	account_name AS accountName,
	password,
	birthdate,
	sex_kbn AS sexKbn,
	birthplace_prefecture_kbn_code AS birthplacePrefectureKbnCode,
	resident_prefecture_kbn_code AS residentPrefectureKbnCode,
	free_memo AS freeMemo,
	authority_kbn AS authorityKbn,
	last_login_datetime AS lastLoginDatetime,
	login_failure_count AS loginFailureCount
FROM
	common.account

	 AND account_no = #{accountNo, typeHandler=com.web.gallery.type_handler.AccountNoTypeHandler}
	 AND is_deleted = #{isDeleted, typeHandler=com.web.gallery.type_handler.IsDeletedTypeHandler}
	 AND account_id = #{accountId, typeHandler=com.web.gallery.type_handler.AccountIdTypeHandler}
	 AND account_name = #{accountName, typeHandler=com.web.gallery.type_handler.AccountNameTypeHandler}
	 AND password = #{password, typeHandler=com.web.gallery.type_handler.PasswordTypeHandler}
	 AND birthdate = #{birthdate, typeHandler=com.web.gallery.type_handler.BirthDateTypeHandler}
	 AND sex_kbn = #{sexKbn}::common.sex_enum
	 AND birthplace_prefecture_kbn_code = #{birthplacePrefectureKbnCode, typeHandler=com.web.gallery.type_handler.BirthplacePrefectureKbnCodeTypeHandler}
	 AND resident_prefecture_kbn_code = #{residentPrefectureKbnCode, typeHandler=com.web.gallery.type_handler.ResidentPrefectureKbnCodeTypeHandler}
	 AND free_memo = #{freeMemo, typeHandler=com.web.gallery.type_handler.FreeMemoTypeHandler}
	 AND authority_kbn = #{authorityKbn}::common.authority_enum
	 AND last_login_datetime = #{lastLoginDatetime}
	 AND login_failure_count = #{loginFailureCount}

